import React, { isValidElement, useEffect, useRef, useState, type ReactElement } from 'react';
import { isObject } from '@arco-design/web-react/es/_util/is';
import { Popover } from '@arco-design/web-react';
import cls from 'classnames';
import { IFormItemLabelProps } from './interface';
import { useFormLayout } from '../FormLayout';
import { usePrefixCls } from '../__builtins__';
import { get, omit } from 'lodash';
import {
  IconQuestionCircle
} from '@arco-design/web-react/icon';

function useOverflow<Container extends HTMLElement, Content extends HTMLElement>() {
  const [overflow, setOverflow] = useState(false);
  const containerRef = useRef<Container>(null);
  const contentRef = useRef<Content>(null);
  const layout = useFormLayout();
  const labelCol = JSON.stringify(layout.labelCol);

  useEffect(() => {
    requestAnimationFrame(() => {
      if (containerRef.current && contentRef.current) {
        const contentWidth = contentRef.current.getBoundingClientRect().width;
        const containerWidth = containerRef.current.getBoundingClientRect().width;
        // contentWidth与containerWidth会出现浮点数情况，计算出现误差，导致展示overflow为true
        if (contentWidth && containerWidth
          && !(Math.abs(containerWidth - contentWidth) < 0.1)
          && containerWidth < contentWidth) {
          if (!overflow) {
            setOverflow(true);
          }
        } else {
          if (overflow) {
            setOverflow(false);
          }
        }
      }
    });
  }, [labelCol]);

  return {
    overflow,
    containerRef,
    contentRef,
  };
}

// 标签
const FormItemLabel: React.FC<IFormItemLabelProps> = ({
  showColon = true,
  label,
  requiredSymbol,
  required,
  tooltip,
  labelAlign,
  labelWrap,
  labelCol,
  labelStyle,
  enableCol = false,
  requiredAlign = false,
  layout
}) => {
  const { containerRef, contentRef, overflow } = useOverflow<HTMLDivElement, HTMLSpanElement>();
  const prefixCls = usePrefixCls('formily-item');

  const symbolPosition = isObject(requiredSymbol) ? requiredSymbol.position : 'start';
  const symbolNode = required && Boolean(requiredSymbol) && (
    <strong className={`${prefixCls}-label-symbol`} style={symbolPosition === 'end' ? { marginLeft: 2 } : { marginRight: 2 }}>
      <svg width="8" height="8" viewBox="0 0 8 8" fill="none" xmlns="http://www.w3.org/2000/svg">
        <path
          fillRule="evenodd"
          clipRule="evenodd"
          d="M4.42164 1.06348C4.53209 1.06348 4.6216 1.15309 4.6216 1.26355L4.62074 3.30847L6.45717 2.71216C6.56222 2.67803 6.67498 2.7354 6.70912 2.84045L6.95643 3.60132C6.99056 3.70637 6.93307 3.81926 6.82802 3.85339L4.97767 4.45349L6.20289 6.14014C6.26781 6.2295 6.24806 6.35451 6.15871 6.41943L5.51149 6.88965C5.42213 6.95457 5.29699 6.93482 5.23207 6.84546L3.96571 5.10144L2.69252 6.85461C2.6276 6.94397 2.50246 6.96386 2.4131 6.89893L1.76588 6.42871C1.67652 6.36379 1.65677 6.23865 1.72169 6.14929L2.9767 4.41956L1.17201 3.8335C1.06696 3.79937 1.00946 3.68659 1.04359 3.58154L1.29079 2.82068C1.32492 2.71563 1.43769 2.65813 1.54274 2.69226L3.42067 3.30151L3.42164 1.26355C3.42164 1.15309 3.51114 1.06348 3.6216 1.06348H4.42164Z"
          fill="#F53F3F"
        />
      </svg>
    </strong >
  );

  const renderLabelText = () => {
    const labelChildren = (
      <div className={`${prefixCls}-label-content`} ref={containerRef}>
        <span ref={contentRef}>
          {symbolPosition !== 'end' && <>{symbolNode}</>}
          <label style={requiredAlign && !symbolNode && symbolPosition !== 'end' && layout === 'horizontal' ? { marginLeft: '12px' } : {}}>
            {label}
          </label>
          {symbolPosition === 'end' && <>{symbolNode}</>}
        </span>
      </div>
    );

    if ((tooltip && tooltip.tooltipLayout === 'text') || overflow) {
      return <Popover {...omit(tooltip, ['tooltipIcon', 'tooltipLayout, customRender', 'content'])} content={tooltip?.content ?? label}>{labelChildren}</Popover>;
    }

    return labelChildren;
  };

  const renderTooltipIcon = () => {
    if (tooltip && get(tooltip, 'tooltipLayout', 'icon') === 'icon' && tooltip.content && !overflow) {
      const tooltipIconClassName = `${prefixCls}-tooltip`;
      if (tooltip.customRender) {
        return <span className={cls(tooltipIconClassName)}>{tooltip.customRender()}</span>;
      }
      let tooltipIcon = get(tooltip, 'tooltipIcon', <IconQuestionCircle />);
      if (isValidElement(tooltipIcon)) {
        tooltipIcon = React.cloneElement(tooltipIcon as ReactElement, {
          className: cls(tooltipIconClassName, (tooltipIcon as ReactElement).props.className)
        });
      }
      return (
        <span>
          <Popover {...omit(tooltip, ['tooltipIcon', 'tooltipLayout, customRender', 'content'])} content={tooltip?.content}>{tooltipIcon}</Popover>
        </span>
      );
    }
    return null;
  };

  return label ? (
    <div
      className={cls({
        [`${prefixCls}-label`]: true,
        [`${prefixCls}-label-tooltip`]: (tooltip && tooltip.tooltipLayout === 'text') || overflow,
        [`${prefixCls}-label-wrap`]: labelWrap,
        [`${prefixCls}-label-align-${labelAlign}`]: true,
        [`${prefixCls}-col-${labelCol}`]: enableCol,
      })}
      style={labelStyle}
    >
      {renderLabelText()}
      {renderTooltipIcon()}
      {showColon ? ':' : ''}
    </div>
  ) : null;
};

export default FormItemLabel;
